import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Router, Route, Switch, useLocation, useParams } from "wouter";
import {
  ArrowLeft, ArrowRight, Archive, Bell, Bookmark, BookmarkIcon, Camera, Check,
  ChevronDown, ChevronRight, Eye, EyeOff, Globe, Grid3X3, Hash, Heart,
  Home as HomeIcon, Image as ImageIcon, Info, Lock, LogOut, MapPin, MessageCircle,
  MessageSquarePlus, MoreHorizontal, Moon, Paperclip, Phone, Play, Plus,
  Search as SearchIcon, Send, Settings as SettingsIcon, Share2, Shield, Sparkles,
  Sun, User, UserPlus, Users, Video, WifiOff, X,
} from "lucide-react";
import "./index.css";

const GRADIENT = "linear-gradient(135deg,#FF006E 0%,#8B00FF 100%)";
const IMG = {
  neon: "/scene-neon.jpg",
  roof: "/scene-rooftop.jpg",
  flower: "/scene-flower.jpg",
  dj: "/scene-dj.jpg",
};

type DemoUser = { id: string; username: string; displayName: string; avatar: string; bio: string; followers: number; following: number; posts: number; verified?: boolean; };
type DemoPost = { id: string; user: DemoUser; image: string; caption: string; hashtags: string[]; likes: number; comments: number; shares: number; views: number; location?: string; };
type DemoStory = { id: string; user: DemoUser; image: string; viewed?: boolean; };

const currentUser: DemoUser = { id: "me", username: "maya.chen", displayName: "Maya Chen", avatar: IMG.neon, bio: "Collecting little sparks from everywhere.", followers: 1248, following: 384, posts: 87, verified: true };
const people: DemoUser[] = [
  currentUser,
  { id: "1", username: "sofia.park", displayName: "Sofia Park", avatar: IMG.roof, bio: "Light leaks and late trains.", followers: 4820, following: 612, posts: 132 },
  { id: "2", username: "noah.reyes", displayName: "Noah Reyes", avatar: IMG.dj, bio: "Sound, motion, after dark.", followers: 905, following: 202, posts: 64, verified: true },
  { id: "3", username: "lina.rose", displayName: "Lina Rose", avatar: IMG.flower, bio: "A soft spot for strange flowers.", followers: 3204, following: 244, posts: 210 },
];
const stories: DemoStory[] = [
  { id: "s1", user: people[1], image: IMG.roof }, { id: "s2", user: people[2], image: IMG.dj },
  { id: "s3", user: people[3], image: IMG.flower, viewed: true },
];
const posts: DemoPost[] = [
  { id: "p1", user: people[1], image: IMG.roof, caption: "Found a little more color on the way home.", hashtags: ["#nightwalk", "#citylight"], likes: 1247, comments: 38, shares: 17, views: 8400, location: "Seoul, South Korea" },
  { id: "p2", user: people[2], image: IMG.dj, caption: "The room changes when the bass comes in.", hashtags: ["#afterdark", "#soundcheck"], likes: 892, comments: 24, shares: 12, views: 5200 },
  { id: "p3", user: people[3], image: IMG.flower, caption: "Tiny worlds hiding in plain sight.", hashtags: ["#softfocus"], likes: 634, comments: 19, shares: 8, views: 3100, location: "Lisbon, Portugal" },
];

function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function Avatar({ user, size = "md", ring = false }: { user: DemoUser; size?: "sm" | "md" | "lg"; ring?: boolean }) {
  const sizes = { sm: "w-8 h-8", md: "w-11 h-11", lg: "w-20 h-20" };
  return <div className={`${sizes[size]} rounded-full p-[2px] shrink-0`} style={ring ? { background: GRADIENT } : undefined}>
    <div className="w-full h-full rounded-full overflow-hidden" style={{ background: "rgba(255,255,255,.1)" }}>
      {user.avatar ? <img src={user.avatar} alt={user.displayName} className="w-full h-full object-cover" /> : <span className="w-full h-full flex items-center justify-center text-white/80 font-bold">{initials(user.displayName)}</span>}
    </div>
  </div>;
}

function Splash({ onDone }: { onDone: () => void }) {
  useEffect(() => { const timer = window.setTimeout(onDone, 1750); return () => window.clearTimeout(timer); }, [onDone]);
  return <motion.div className="fixed inset-0 z-[999] flex flex-col items-center justify-center gradient-bg" initial={{ opacity: 1 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: .35 }}>
    <motion.div initial={{ scale: .7, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ duration: .55, ease: [0.34, 1.56, 0.64, 1] }} className="flex flex-col items-center gap-4">
      <div className="w-28 h-28 rounded-3xl bg-white/15 flex items-center justify-center shadow-2xl"><Sparkles size={50} className="text-white" strokeWidth={1.6} /></div>
      <motion.span initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: .22 }} className="text-white text-4xl font-black tracking-tight">Yuniko</motion.span>
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: .48 }} className="mt-10 flex flex-col items-center gap-1">
        <span className="text-white/90 text-sm font-semibold tracking-wide">Aora Group</span>
        <div className="flex gap-1.5 mt-3">{[0, 1, 2].map((i) => <motion.div key={i} className="w-1.5 h-1.5 rounded-full bg-white/75" animate={{ scale: [1, 1.4, 1], opacity: [.7, 1, .7] }} transition={{ repeat: Infinity, duration: .9, delay: i * .18 }} />)}</div>
      </motion.div>
    </motion.div>
  </motion.div>;
}

function BottomNav() {
  const [location, navigate] = useLocation();
  const items = [{ path: "/", label: "Home", icon: HomeIcon }, { path: "/notifications", label: "Alerts", icon: Bell }, { path: "/messages", label: "Messages", icon: MessageCircle }, { path: "/profile", label: "Profile", icon: User }];
  const active = (path: string) => path === "/" ? location === "/" : location.startsWith(path);
  return <nav className="fixed bottom-0 left-0 right-0 z-50 yuniko-bottom-nav" style={{ background: "rgba(10,8,18,.95)", backdropFilter: "blur(24px)", borderTop: "1px solid rgba(255,61,154,.15)" }}>
    <div className="flex items-center justify-around h-16 max-w-[1120px] mx-auto px-2">
      {items.slice(0, 2).map(({ path, label, icon: Icon }) => <button key={path} aria-label={label} onClick={() => navigate(path)} className="w-14 h-14 flex flex-col items-center justify-center gap-0.5 relative">
        <Icon size={22} style={{ color: active(path) ? "#FF3D9A" : "rgba(255,255,255,.45)" }} strokeWidth={active(path) ? 2.3 : 1.7} /><span className="text-[10px]" style={{ color: active(path) ? "#FF3D9A" : "rgba(255,255,255,.38)" }}>{label}</span><span className="absolute bottom-0 w-1 h-1 rounded-full" style={{ background: "#FF3D9A", opacity: active(path) ? 1 : 0 }} />
      </button>)}
      <motion.button aria-label="Create" onClick={() => navigate("/create")} whileTap={{ scale: .88 }} className="w-[52px] h-[52px] rounded-full flex items-center justify-center" style={{ background: GRADIENT, boxShadow: "0 0 24px rgba(255,0,110,.45)" }}><Plus size={25} className="text-white" strokeWidth={2.8} /></motion.button>
      {items.slice(2).map(({ path, label, icon: Icon }) => <button key={path} aria-label={label} onClick={() => navigate(path)} className="w-14 h-14 flex flex-col items-center justify-center gap-0.5 relative">
        <Icon size={22} style={{ color: active(path) ? "#FF3D9A" : "rgba(255,255,255,.45)" }} strokeWidth={active(path) ? 2.3 : 1.7} /><span className="text-[10px]" style={{ color: active(path) ? "#FF3D9A" : "rgba(255,255,255,.38)" }}>{label}</span><span className="absolute bottom-0 w-1 h-1 rounded-full" style={{ background: "#FF3D9A", opacity: active(path) ? 1 : 0 }} />
      </button>)}
    </div>
  </nav>;
}

function PageShell({ children, nav = true, className = "" }: { children: ReactNode; nav?: boolean; className?: string }) {
  return <div className={`w-full min-h-screen bg-[#0d0b14] text-white ${nav ? "pb-20" : ""} ${className}`}>{children}{nav && <BottomNav />}</div>;
}

function StoryStrip() {
  const [, navigate] = useLocation();
  return <div className="absolute inset-x-0 z-40 h-[78px] top-14 glass border-b border-white/5"><div className="flex items-center gap-3 h-full px-3 overflow-x-auto no-scrollbar">
    <motion.button whileTap={{ scale: .9 }} onClick={() => navigate("/create?mode=story")} className="flex flex-col items-center gap-1 min-w-16"><div className="relative w-[54px] h-[54px] rounded-full p-[2px] border-2 border-dashed border-pink-400/50"><Avatar user={currentUser} size="md" /><span className="absolute bottom-0 right-0 w-[18px] h-[18px] rounded-full flex items-center justify-center border-2 border-[#0d0b14]" style={{ background: GRADIENT }}><Plus size={9} /></span></div><span className="text-white/65 text-[10px]">Your story</span></motion.button>
    {stories.map((story) => <motion.button key={story.id} whileTap={{ scale: .9 }} onClick={() => navigate(`/story/${story.id}`)} className="flex flex-col items-center gap-1 min-w-16"><div className="w-[54px] h-[54px] rounded-full p-[2px]" style={{ background: story.viewed ? "rgba(255,255,255,.14)" : GRADIENT }}><div className="w-full h-full rounded-full overflow-hidden border-2 border-[#0d0b14]"><img src={story.user.avatar} alt={story.user.displayName} className="w-full h-full object-cover" /></div></div><span className="text-white/65 text-[10px] truncate max-w-[60px]">{story.user.displayName.split(" ")[0]}</span></motion.button>)}
  </div></div>;
}

function PostCard({ post }: { post: DemoPost }) {
  const [, navigate] = useLocation();
  const [liked, setLiked] = useState(false);
  const [saved, setSaved] = useState(false);
  const [comments, setComments] = useState(false);
  const [comment, setComment] = useState("");
  const [commentCount, setCommentCount] = useState(post.comments);
  const [burst, setBurst] = useState(false);
  const lastTap = useRef(0);
  const tapImage = () => { const now = Date.now(); if (now - lastTap.current < 320) { setLiked(true); setBurst(true); window.setTimeout(() => setBurst(false), 700); } lastTap.current = now; };
  return <div className="relative w-full h-full" data-testid={`post-card-${post.id}`}>
    <img src={post.image} alt={post.caption} className="absolute inset-0 w-full h-full object-cover" onClick={tapImage} />
    <div className="absolute inset-0 pointer-events-none" style={{ background: "linear-gradient(to top,rgba(0,0,0,.9),rgba(0,0,0,.22) 50%,transparent 72%)" }} />
    <div className="absolute top-3 left-3 flex items-center gap-1.5 rounded-full px-2.5 py-1 bg-black/40 backdrop-blur-md"><Eye size={12} className="text-white/75" /><span className="text-white/80 text-[11px] font-semibold">{post.views.toLocaleString()}</span></div>
    <motion.button whileTap={{ scale: .88 }} aria-label="Post options" onClick={() => navigate(`/post/${post.id}`)} className="absolute top-3 right-3 p-2 rounded-full bg-black/35 backdrop-blur-md"><MoreHorizontal size={18} /></motion.button>
    <AnimatePresence>{burst && <motion.div initial={{ scale: .4, opacity: 1 }} animate={{ scale: 1.5, opacity: 0 }} exit={{ opacity: 0 }} transition={{ duration: .65 }} className="absolute inset-0 flex items-center justify-center pointer-events-none"><Heart size={100} className="fill-red-500 text-red-500" /></motion.div>}</AnimatePresence>
    <div className="absolute right-3 bottom-24 flex flex-col items-center gap-4 z-10">
      <ActionButton label={liked ? String(post.likes + 1) : String(post.likes)} onClick={() => setLiked(!liked)}><Heart size={25} className={liked ? "fill-red-500 text-red-500" : "text-white"} strokeWidth={1.8} /></ActionButton>
      <ActionButton label={String(commentCount)} onClick={() => setComments(true)}><MessageCircle size={25} strokeWidth={1.8} /></ActionButton>
      <ActionButton label={String(post.shares)} onClick={() => navigator.clipboard?.writeText(`${window.location.origin}/post/${post.id}`)}><Share2 size={25} strokeWidth={1.8} /></ActionButton>
      <ActionButton label={saved ? String(post.likes + 1) : String(post.likes)} onClick={() => setSaved(!saved)}><Bookmark size={25} className={saved ? "fill-yellow-400 text-yellow-400" : ""} strokeWidth={1.8} /></ActionButton>
    </div>
    <div className="absolute bottom-4 left-3 right-20 z-10">
      <div className="flex items-center gap-2.5 mb-1.5"><button onClick={() => navigate(`/user/${post.user.id}`)}><Avatar user={post.user} size="sm" ring /></button><div className="flex-1 min-w-0"><button onClick={() => navigate(`/user/${post.user.id}`)} className="font-semibold text-sm">{post.user.displayName}</button><p className="text-white/55 text-xs">{post.location ?? "World Feed"}</p></div><button className="px-3.5 py-1 rounded-full text-xs font-semibold bg-white/15 border border-white/15">Follow</button></div>
      <p className="text-white text-sm font-medium leading-snug line-clamp-2">{post.caption}</p><p className="text-pink-300 text-sm mt-0.5">{post.hashtags.join(" ")}</p><p className="text-white/40 text-xs mt-0.5">2h ago</p>
    </div>
    <AnimatePresence>{comments && <><motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[60] bg-black/60" onClick={() => setComments(false)} /><motion.div initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ type: "spring", damping: 28, stiffness: 340 }} className="fixed bottom-0 left-0 right-0 mx-auto z-[61] max-w-[1100px] rounded-t-3xl flex flex-col" style={{ maxHeight: "72vh", background: "rgba(14,11,24,.98)", border: "1px solid rgba(255,255,255,.09)" }}>
        <div className="w-10 h-1 rounded-full bg-white/20 mx-auto mt-3" /><div className="flex items-center justify-between px-5 py-4 border-b border-white/10"><span className="font-semibold text-sm">Comments ({commentCount})</span><button onClick={() => setComments(false)}><X size={18} className="text-white/60" /></button></div>
        <div className="flex-1 p-5"><div className="flex gap-3 mb-5"><Avatar user={people[3]} size="sm" /><p className="text-white/80 text-sm">Love the colors in this one.</p></div><div className="flex gap-3"><Avatar user={people[2]} size="sm" /><p className="text-white/80 text-sm">This feels like a whole movie.</p></div></div>
        <form className="flex items-center gap-3 p-4 border-t border-white/10 pb-safe" onSubmit={(e) => { e.preventDefault(); if (comment.trim()) { setCommentCount((n) => n + 1); setComment(""); } }}><input aria-label="Add a comment" value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Add a comment…" className="flex-1 bg-white/[.06] border border-white/10 rounded-full px-4 py-2.5 text-sm outline-none placeholder:text-white/35" /><button aria-label="Send comment" className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: comment.trim() ? GRADIENT : "rgba(255,255,255,.08)" }}><Send size={15} /></button></form>
      </motion.div></>}</AnimatePresence>
  </div>;
}
function ActionButton({ children, label, onClick }: { children: ReactNode; label: string; onClick: () => void }) { return <motion.button whileTap={{ scale: .85 }} onClick={onClick} className="flex flex-col items-center gap-0.5"><span className="w-11 h-11 rounded-full bg-black/45 backdrop-blur-md flex items-center justify-center">{children}</span><span className="text-white text-[11px] font-medium">{label}</span></motion.button>; }

function Home() {
  const [, navigate] = useLocation();
  const [worldMenu, setWorldMenu] = useState(false);
  const [online, setOnline] = useState(true);
  useEffect(() => { const on = () => setOnline(true); const off = () => setOnline(false); window.addEventListener("online", on); window.addEventListener("offline", off); return () => { window.removeEventListener("online", on); window.removeEventListener("offline", off); }; }, []);
  return <PageShell><div className="relative w-full min-h-screen bg-[#0d0b14] overflow-hidden">
    <header className="absolute inset-x-0 top-0 z-50 h-14 flex items-center justify-between gap-2 px-3 min-[360px]:px-4 glass border-b border-pink-400/10"><button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} className="text-2xl font-black gradient-text">Yuniko</button><button onClick={() => setWorldMenu(!worldMenu)} className="flex items-center gap-1 px-3 py-1.5 rounded-full bg-white/[.06] border border-pink-400/30 text-white/90 text-xs min-[360px]:text-sm"><Globe size={12} />World Feed<ChevronDown size={11} /></button><div className="flex items-center gap-3"><button aria-label="Search" onClick={() => navigate("/search")}><SearchIcon size={20} className="text-white/75" /></button><button aria-label="Add friends" onClick={() => navigate("/add-friends")}><UserPlus size={20} className="text-white/75" /></button></div></header>
    <StoryStrip />
    {worldMenu && <><button className="fixed inset-0 z-40 cursor-default" onClick={() => setWorldMenu(false)} aria-label="Close menu" /><motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} className="absolute top-[60px] left-1/2 -translate-x-1/2 w-44 rounded-2xl z-50 overflow-hidden bg-[#120e1e] border border-pink-400/25"><button onClick={() => setWorldMenu(false)} className="w-full px-4 py-3 text-left text-sm flex items-center gap-2"><Globe size={13} />World Feed</button></motion.div></>}
    {!online && <div className="absolute inset-x-0 top-[134px] z-40 flex items-center justify-center gap-1.5 py-1.5 bg-red-500/85"><WifiOff size={12} /><span className="text-xs">Offline</span></div>}
    <div className="absolute inset-x-0 top-[134px] bottom-[64px] overflow-y-scroll snap-y snap-mandatory no-scrollbar" data-testid="posts-feed">{posts.map((post) => <div key={post.id} className="relative w-full px-2 py-1 snap-start snap-always" style={{ height: "calc(100dvh - 198px)" }}><div className="relative w-full h-full rounded-2xl overflow-hidden"><PostCard post={post} /></div></div>)}</div>
  </div></PageShell>;
}

function Login({ onLogin }: { onLogin: () => void }) {
  const [, navigate] = useLocation();
  const [mode, setMode] = useState<"signin" | "signup" | "forgot">("signin");
  const [step, setStep] = useState(1);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const submit = () => { if (!username.trim() || !password) { setError("Please fill in all fields"); return; } onLogin(); navigate("/"); };
  const Field = ({ icon, value, onChange, placeholder, type = "text", suffix }: { icon: ReactNode; value: string; onChange: (value: string) => void; placeholder: string; type?: string; suffix?: ReactNode }) => <div className="flex items-center gap-3 px-4 py-3.5 rounded-2xl bg-white/[.06] border border-white/10">{icon}<input type={type} value={value} onChange={(e) => { onChange(e.target.value); setError(""); }} placeholder={placeholder} className="flex-1 bg-transparent text-white/90 text-sm outline-none placeholder:text-white/30" />{suffix}</div>;
  return <PageShell nav={false} className="flex flex-col"><div className="relative flex flex-col items-center justify-end px-6 pt-14 pb-7 min-h-[220px]"><div className="absolute inset-0" style={{ background: "linear-gradient(180deg,rgba(255,0,110,.17),rgba(139,0,255,.13) 60%,transparent)" }} /><div className="relative flex flex-col items-center"><div className="w-[68px] h-[68px] rounded-[20px] flex items-center justify-center mb-3" style={{ background: GRADIENT, boxShadow: "0 0 44px rgba(255,0,110,.45)" }}><Sparkles size={35} /></div><h1 className="text-2xl font-black gradient-text">Yuniko</h1></div></div>
    <div className="flex-1 px-6 pb-10"><AnimatePresence mode="wait" initial={false}>
      {mode === "signin" && <motion.div key="signin" initial={{ opacity: 0, x: -24 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 24 }}><div className="flex p-1 rounded-2xl mb-6 bg-white/[.06] border border-white/10"><button className="flex-1 py-2.5 rounded-xl text-sm font-semibold text-white" style={{ background: GRADIENT }}>Sign In</button><button onClick={() => { setMode("signup"); setError(""); }} className="flex-1 py-2.5 rounded-xl text-sm font-semibold text-white/50">Sign Up</button></div><div className="flex flex-col gap-3 mb-4"><Field icon={<User size={18} className="text-white/40" />} value={username} onChange={setUsername} placeholder="Username" /><Field icon={<Lock size={18} className="text-white/40" />} value={password} onChange={setPassword} placeholder="Password" type={showPw ? "text" : "password"} suffix={<button aria-label="Toggle password" onClick={() => setShowPw(!showPw)}>{showPw ? <EyeOff size={16} className="text-white/40" /> : <Eye size={16} className="text-white/40" />}</button>} /></div><div className="text-right mb-5"><button onClick={() => { setMode("forgot"); setError(""); }} className="text-sm text-pink-400">Forgot Password?</button></div>{error && <p className="text-red-400 text-xs text-center mb-4">{error}</p>}<button onClick={submit} className="w-full py-4 rounded-2xl text-white font-bold text-sm flex items-center justify-center gap-2" style={{ background: GRADIENT, boxShadow: "0 4px 20px rgba(255,0,110,.35)" }}>Sign In <ArrowRight size={16} /></button><p className="text-center text-white/40 text-sm mt-5">Don't have an account? <button onClick={() => { setMode("signup"); setError(""); }} className="font-semibold text-pink-400">Sign Up</button></p></motion.div>}
      {mode === "signup" && <motion.div key={`signup-${step}`} initial={{ opacity: 0, x: 24 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -24 }}><div className="flex items-center justify-between mb-5"><button onClick={() => step === 1 ? setMode("signin") : setStep(step - 1)}><ArrowLeft size={20} className="text-white/60" /></button><div className="flex gap-1.5">{[1, 2, 3].map((n) => <span key={n} className="h-1.5 rounded-full transition-all" style={{ width: step === n ? 20 : 6, background: n <= step ? GRADIENT : "rgba(255,255,255,.18)" }} />)}</div><span className="w-6" /></div>{step === 1 && <><h2 className="text-xl font-bold mb-1">Create account</h2><p className="text-white/40 text-sm mb-5">Choose a unique username</p><div className="flex flex-col gap-3 mb-5"><Field icon={<span className="text-white/40">@</span>} value={username} onChange={setUsername} placeholder="username" /><Field icon={<Lock size={18} className="text-white/40" />} value={password} onChange={setPassword} placeholder="Password (min 6 characters)" type="password" /><Field icon={<Lock size={18} className="text-white/40" />} value="" onChange={() => undefined} placeholder="Confirm password" type="password" /></div><button onClick={() => { if (username.length < 3 || password.length < 6) setError("Use a username with 3 characters and a password with 6."); else { setError(""); setStep(2); } }} className="w-full py-4 rounded-2xl text-white font-bold text-sm flex items-center justify-center gap-2" style={{ background: GRADIENT }}>Continue <ArrowRight size={16} /></button></>}
      {step === 2 && <><h2 className="text-xl font-bold mb-1">About you</h2><p className="text-white/40 text-sm mb-5">Help others find and know you</p><div className="flex flex-col gap-3 mb-5"><Field icon={<User size={18} className="text-white/40" />} value={name} onChange={setName} placeholder="Display name" /><div className="flex items-center gap-3 px-4 py-3.5 rounded-2xl bg-white/[.06] border border-white/10"><Globe size={18} className="text-white/40" /><input placeholder="Where are you from?" className="flex-1 bg-transparent text-white/90 text-sm outline-none placeholder:text-white/30" /></div><div className="flex items-center gap-3 px-4 py-3.5 rounded-2xl bg-white/[.06] border border-white/10"><Users size={18} className="text-white/40" /><input placeholder="Your age" type="number" className="flex-1 bg-transparent text-white/90 text-sm outline-none placeholder:text-white/30" /></div></div><button onClick={() => setStep(3)} className="w-full py-4 rounded-2xl text-white font-bold text-sm flex items-center justify-center gap-2" style={{ background: GRADIENT }}>Continue <ArrowRight size={16} /></button></>}
      {step === 3 && <><h2 className="text-xl font-bold mb-1">Add your photo</h2><p className="text-white/40 text-sm mb-6">Help people recognize you</p><div className="flex justify-center mb-5"><div className="w-32 h-32 rounded-full flex items-center justify-center border-2 border-dashed border-white/20 bg-white/[.06]"><Camera size={28} className="text-pink-400" /></div></div><button onClick={() => { onLogin(); navigate("/"); }} className="w-full py-4 rounded-2xl text-white font-bold text-sm flex items-center justify-center gap-2" style={{ background: GRADIENT }}>Create Account <ArrowRight size={16} /></button><button onClick={() => { onLogin(); navigate("/"); }} className="w-full py-3 text-white/35 text-sm mt-2">Skip for now</button></>}</motion.div>}
      {mode === "forgot" && <motion.div key="forgot" initial={{ opacity: 0, x: 24 }} animate={{ opacity: 1, x: 0 }}><button onClick={() => setMode("signin")} className="mb-5"><ArrowLeft size={20} className="text-white/60" /></button><h2 className="text-xl font-bold mb-1">Reset password</h2><p className="text-white/40 text-sm mb-5">Enter your username to continue</p><Field icon={<User size={18} className="text-white/40" />} value={username} onChange={setUsername} placeholder="Your username" />{error && <p className="text-red-400 text-xs text-center mt-4">{error}</p>}<button onClick={() => { if (!username.trim()) setError("Please enter your username"); else { setError(""); setMode("signin"); } }} className="w-full py-4 mt-5 rounded-2xl text-white font-bold text-sm flex items-center justify-center gap-2" style={{ background: GRADIENT }}>Continue <ArrowRight size={16} /></button></motion.div>}
    </AnimatePresence></div>
  </PageShell>;
}

function Notifications() { const [, navigate] = useLocation(); return <PageShell><TopBar title="Notifications" back={false} /><div className="px-4 pt-4"><div className="flex items-center gap-3 py-4 border-b border-white/5"><Avatar user={people[2]} size="md" ring /><p className="text-sm text-white/80 flex-1"><b>Noah Reyes</b> liked your post <span className="text-white/40">2m</span></p><img src={IMG.flower} alt="" className="w-12 h-12 rounded-lg object-cover" /></div><div className="flex items-center gap-3 py-4 border-b border-white/5"><Avatar user={people[3]} size="md" ring /><p className="text-sm text-white/80 flex-1"><b>Lina Rose</b> started following you <span className="text-white/40">1h</span></p><button onClick={() => navigate("/user/3")} className="px-3 py-1.5 rounded-full text-xs font-semibold" style={{ background: GRADIENT }}>Follow back</button></div><div className="flex items-center gap-3 py-4 border-b border-white/5"><Avatar user={people[1]} size="md" ring /><p className="text-sm text-white/80 flex-1"><b>Sofia Park</b> mentioned you in a story <span className="text-white/40">3h</span></p><button onClick={() => navigate("/story/s1")}><Play size={18} className="text-pink-400" /></button></div></div></PageShell>; }

function TopBar({ title, back = true, action }: { title: string; back?: boolean; action?: ReactNode }) { const [, navigate] = useLocation(); return <header className="sticky top-0 z-40 px-4 py-4 flex items-center gap-3 glass border-b border-white/[.06]">{back && <button aria-label="Back" onClick={() => window.history.length > 1 ? window.history.back() : navigate("/")}><ArrowLeft size={22} className="text-white/80" /></button>}<h1 className="text-base font-semibold flex-1">{title}</h1>{action}</header>; }

function Create() { const [, navigate] = useLocation(); const [tab, setTab] = useState<"post" | "story">("post"); const [caption, setCaption] = useState(""); const [media, setMedia] = useState<string | null>(null); const [posted, setPosted] = useState(false); const inputRef = useRef<HTMLInputElement>(null); if (posted) return <PageShell nav={false} className="flex flex-col items-center justify-center gap-5"><motion.div initial={{ scale: .5, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="w-20 h-20 rounded-full flex items-center justify-center" style={{ background: GRADIENT }}><Check size={36} /></motion.div><p className="text-white font-semibold text-xl">{tab === "story" ? "Story posted" : "Posted"}</p><button onClick={() => navigate("/")} className="text-pink-400 text-sm">Back to World Feed</button></PageShell>; return <PageShell className="max-w-[1100px] mx-auto"><input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (file) setMedia(URL.createObjectURL(file)); }} /><TopBar title={tab === "story" ? "New Story" : "New Post"} action={<button onClick={() => { if (caption.trim() || media) setPosted(true); }} className="px-4 py-1.5 rounded-full text-sm font-semibold" style={{ background: caption.trim() || media ? GRADIENT : "rgba(255,255,255,.1)", opacity: caption.trim() || media ? 1 : .5 }}>{tab === "story" ? "Share" : "Post"}</button>} /><div className="max-w-xl mx-auto px-4 py-5"><div className="flex p-1 rounded-2xl mb-6 bg-white/[.06] border border-white/10"><button onClick={() => setTab("post")} className="flex-1 py-2.5 rounded-xl text-sm" style={tab === "post" ? { background: GRADIENT } : { color: "rgba(255,255,255,.45)" }}>Post</button><button onClick={() => setTab("story")} className="flex-1 py-2.5 rounded-xl text-sm" style={tab === "story" ? { background: GRADIENT } : { color: "rgba(255,255,255,.45)" }}>Story</button></div><div className="flex gap-3 mb-4"><Avatar user={currentUser} size="md" ring /><textarea value={caption} onChange={(e) => setCaption(e.target.value)} rows={4} placeholder={tab === "story" ? "Add a caption (optional)" : "Add a caption"} className="flex-1 bg-transparent text-white/85 text-sm resize-none outline-none placeholder:text-white/30" /></div>{media && <div className="relative rounded-2xl overflow-hidden mb-4"><img src={media} alt="Selected" className="w-full max-h-[55vh] object-contain bg-white/5" /><button onClick={() => setMedia(null)} className="absolute top-2 right-2 w-8 h-8 rounded-full bg-black/65 flex items-center justify-center"><X size={14} /></button></div>}<div className="flex gap-3 mb-6"><button onClick={() => inputRef.current?.click()} className="flex-1 py-4 rounded-2xl flex flex-col items-center gap-2 bg-pink-500/[.08] border border-pink-500/25"><ImageIcon size={24} className="text-pink-400" /><span className="text-white/70 text-xs">{media ? "Change Photo" : "Add Photo"}</span></button><button onClick={() => setTab("post")} className="flex-1 py-4 rounded-2xl flex flex-col items-center gap-2 bg-violet-500/[.08] border border-violet-500/25"><Video size={24} className="text-violet-300" /><span className="text-white/70 text-xs">Video</span></button></div><div className="rounded-2xl overflow-hidden bg-white/[.04] border border-white/[.07]"><div className="flex items-center gap-3 px-4 py-3.5 border-b border-white/[.06]"><MapPin size={18} className="text-pink-400" /><input placeholder="Add a location" className="flex-1 bg-transparent text-white/80 text-sm outline-none placeholder:text-white/30" /></div><div className="flex items-center gap-3 px-4 py-3.5"><Hash size={18} className="text-blue-400" /><input placeholder="Add hashtags" className="flex-1 bg-transparent text-white/80 text-sm outline-none placeholder:text-white/30" /></div></div></div></PageShell>; }

function Messages() { const [, navigate] = useLocation(); const [query, setQuery] = useState(""); const conversations = useMemo(() => [{ user: people[1], last: "That light is unreal.", time: "2m", unread: 2, online: true }, { user: people[2], last: "See you after soundcheck.", time: "1h", unread: 0, online: true }, { user: people[3], last: "Sent a photo", time: "3h", unread: 4, online: false }].filter((item) => item.user.displayName.toLowerCase().includes(query.toLowerCase())), [query]); return <PageShell><TopBar title="Messages" back={false} action={<button aria-label="New message" onClick={() => navigate("/search")}><MessageSquarePlus size={21} /></button>} /><div className="px-4 py-3"><div className="flex items-center gap-2.5 px-3 py-2.5 rounded-2xl bg-white/[.06] border border-white/[.08]"><SearchIcon size={16} className="text-white/40" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search messages" className="flex-1 bg-transparent text-white/80 text-sm outline-none placeholder:text-white/30" /></div></div><div>{conversations.length === 0 ? <EmptyState icon={<MessageSquarePlus size={28} />} title="No messages yet" body="Start a conversation with someone new." /> : conversations.map((item) => <button key={item.user.id} onClick={() => navigate(`/chat/${item.user.id}`)} className="w-full flex items-center gap-3 px-4 py-3.5 text-left border-b border-white/[.05]"><div className="relative"><Avatar user={item.user} size="md" />{item.online && <span className="absolute bottom-0 right-0 w-3 h-3 rounded-full bg-green-400 border-2 border-[#0d0b14]" />}</div><div className="flex-1 min-w-0"><div className="flex justify-between"><span className="font-semibold text-sm">{item.user.displayName}</span><span className="text-xs text-pink-400">{item.time}</span></div><div className="flex justify-between mt-0.5"><p className="text-sm truncate text-white/55">{item.last}</p>{item.unread > 0 && <span className="min-w-5 h-5 px-1 rounded-full text-white text-[11px] font-bold flex items-center justify-center" style={{ background: GRADIENT }}>{item.unread}</span>}</div></div><button onClick={(e) => e.stopPropagation()} aria-label="Archive conversation" className="w-9 h-9 rounded-full bg-white/5 flex items-center justify-center"><Archive size={16} className="text-white/50" /></button></button>)}</div></PageShell>; }

function EmptyState({ icon, title, body }: { icon: ReactNode; title: string; body: string }) { return <div className="flex flex-col items-center justify-center py-24 px-6 text-center"><div className="w-16 h-16 rounded-full flex items-center justify-center mb-4 bg-pink-500/10 border border-pink-500/20 text-pink-400">{icon}</div><h2 className="font-bold text-lg mb-2">{title}</h2><p className="text-white/45 text-sm">{body}</p></div>; }

function Profile({ userId }: { userId?: string }) { const [, navigate] = useLocation(); const user = userId && userId !== "me" ? people.find((person) => person.id === userId) ?? people[1] : currentUser; const [following, setFollowing] = useState(false); const [tab, setTab] = useState<"grid" | "saved">("grid"); return <PageShell><TopBar title={`@${user.username}`} action={user.id === "me" ? <button aria-label="Settings" onClick={() => navigate("/settings")}><SettingsIcon size={22} className="text-white/80" /></button> : <button aria-label="More"><MoreHorizontal size={22} className="text-white/80" /></button>} /><div className="h-32" style={{ background: GRADIENT }} /><div className="px-4 relative"><div className="flex items-end justify-between -mt-9 mb-3"><Avatar user={user} size="lg" ring />{user.id !== "me" && <div className="flex gap-2"><button onClick={() => setFollowing(!following)} className="px-5 py-2 rounded-xl text-sm font-semibold" style={{ background: following ? "rgba(255,255,255,.1)" : GRADIENT }}>{following ? "Following" : "Follow"}</button><button aria-label="Message" onClick={() => navigate(`/chat/${user.id}`)} className="w-9 h-9 rounded-xl bg-white/10 flex items-center justify-center"><MessageCircle size={16} /></button><button aria-label="Call" className="w-9 h-9 rounded-xl bg-white/10 flex items-center justify-center"><Phone size={16} /></button></div>}</div><div className="mb-4"><div className="flex items-center gap-1"><h2 className="font-bold text-base">{user.displayName}</h2>{user.verified && <Check size={14} className="text-blue-400" />}</div><p className="text-white/50 text-sm">@{user.username}</p><p className="text-white/80 text-sm mt-2">{user.bio}</p><p className="text-white/45 text-xs mt-2"><MapPin size={12} className="inline" /> World, always</p></div><div className="flex rounded-2xl mb-4 overflow-hidden bg-white/[.04] border border-white/[.07]"><Stat label="Posts" value={user.posts} /><button onClick={() => navigate(`/followers/${user.id}`)} className="flex-1 py-3 border-r border-white/[.07]"><b className="block">{user.followers}</b><span className="text-white/45 text-xs">Followers</span></button><button onClick={() => navigate(`/following/${user.id}`)} className="flex-1 py-3"><b className="block">{user.following}</b><span className="text-white/45 text-xs">Following</span></button></div><div className="flex border-b border-white/5 mb-2"><button aria-label="Posts" onClick={() => setTab("grid")} className={`flex-1 py-3 ${tab === "grid" ? "text-pink-400" : "text-white/40"}`}><Grid3X3 size={18} className="mx-auto" /></button><button aria-label="Saved" onClick={() => setTab("saved")} className={`flex-1 py-3 ${tab === "saved" ? "text-pink-400" : "text-white/40"}`}><BookmarkIcon size={18} className="mx-auto" /></button></div><div className="grid grid-cols-3 gap-1">{posts.concat(posts[0]).slice(0, 4).map((post) => <button key={post.id} onClick={() => navigate(`/post/${post.id}`)} className="aspect-square bg-white/5 overflow-hidden"><img src={post.image} alt={post.caption} className="w-full h-full object-cover" /></button>)}</div></div></PageShell>; }
function Stat({ label, value }: { label: string; value: number }) { return <div className="flex-1 py-3 text-center border-r border-white/[.07]"><b className="block">{value}</b><span className="text-white/45 text-xs">{label}</span></div>; }

function SearchPage() { const [, navigate] = useLocation(); const [query, setQuery] = useState(""); const result = people.filter((person) => `${person.displayName} ${person.username}`.toLowerCase().includes(query.toLowerCase())); return <PageShell><TopBar title="Search" /><div className="px-4 py-3"><div className="flex items-center gap-2.5 px-3 py-2.5 rounded-2xl bg-white/[.06] border border-white/[.08]"><SearchIcon size={16} className="text-white/40" /><input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search people and tags" className="flex-1 bg-transparent text-white/80 text-sm outline-none placeholder:text-white/30" /></div></div><div className="px-4"><p className="text-white/40 text-xs uppercase tracking-wider mb-3">People</p>{result.map((person) => <button key={person.id} onClick={() => navigate(`/user/${person.id}`)} className="w-full flex items-center gap-3 py-3 text-left"><Avatar user={person} size="md" ring /><div><p className="font-semibold text-sm">{person.displayName}</p><p className="text-white/45 text-xs">@{person.username}</p></div><ChevronRight size={16} className="ml-auto text-white/25" /></button>)}</div></PageShell>; }

function StoryPage() { const params = useParams<{ id?: string }>(); const story = stories.find((item) => item.id === params.id) ?? stories[0]; const [, navigate] = useLocation(); return <PageShell nav={false} className="bg-black flex flex-col"><div className="relative flex-1 min-h-[100dvh] overflow-hidden"><img src={story.image} alt={story.user.displayName} className="absolute inset-0 w-full h-full object-cover" /><div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/50" /><div className="absolute top-3 inset-x-0 px-4 pt-safe"><div className="h-1 rounded-full bg-white/25 overflow-hidden"><motion.div initial={{ width: 0 }} animate={{ width: "100%" }} transition={{ duration: 5 }} className="h-full bg-white" /></div><div className="flex items-center gap-3 mt-4"><Avatar user={story.user} size="sm" ring /><div className="flex-1"><p className="font-semibold text-sm">{story.user.displayName}</p><p className="text-white/60 text-xs">2h ago</p></div><button aria-label="Close story" onClick={() => navigate("/")}><X size={22} /></button></div></div><div className="absolute bottom-10 inset-x-0 text-center px-8"><p className="text-2xl font-black">Find your way into the night.</p><div className="flex items-center gap-2 mt-6"><input placeholder="Reply to story" className="flex-1 bg-black/35 border border-white/20 rounded-full px-4 py-3 text-sm outline-none placeholder:text-white/60" /><button aria-label="Send story reply" className="w-11 h-11 rounded-full flex items-center justify-center" style={{ background: GRADIENT }}><Send size={17} /></button></div></div></div></PageShell>; }

function Chat() { const params = useParams<{ userId?: string }>(); const contact = people.find((person) => person.id === params.userId) ?? people[1]; const [text, setText] = useState(""); const [messages, setMessages] = useState(["That light is unreal.", "I know, right? It felt like the whole street was glowing."]); return <PageShell nav={false} className="flex flex-col h-[100dvh]"><TopBar title={contact.displayName} action={<div className="flex gap-3"><button aria-label="Voice call"><Phone size={19} /></button><button aria-label="Video call"><Video size={19} /></button></div>} /><div className="flex-1 overflow-y-auto px-4 py-5 space-y-3">{messages.map((message, index) => <div key={`${message}-${index}`} className={`flex ${index % 2 ? "justify-end" : "justify-start"}`}><p className={`max-w-[78%] px-4 py-3 rounded-2xl text-sm ${index % 2 ? "rounded-br-md text-white" : "rounded-bl-md bg-white/[.08] text-white/80"}`} style={index % 2 ? { background: GRADIENT } : undefined}>{message}</p></div>)}</div><form onSubmit={(e) => { e.preventDefault(); if (text.trim()) { setMessages([...messages, text.trim()]); setText(""); } }} className="flex gap-2 items-center p-3 border-t border-white/10 glass pb-safe"><button aria-label="Attach"><Paperclip size={20} className="text-white/50" /></button><input value={text} onChange={(e) => setText(e.target.value)} placeholder="Write a message" className="flex-1 bg-white/[.06] rounded-full px-4 py-3 text-sm outline-none placeholder:text-white/35" /><button aria-label="Send" className="w-10 h-10 rounded-full flex items-center justify-center" style={{ background: text.trim() ? GRADIENT : "rgba(255,255,255,.08)" }}><Send size={16} /></button></form></PageShell>; }

function Settings() { const [, navigate] = useLocation(); const [theme, setTheme] = useState("dark"); const [logout, setLogout] = useState(false); const sections = [{ title: "Account", color: "#ff3d9a", items: [["Edit Profile", "/profile/edit", User], ["Username & Email", "/settings/account", User], ["Verify Account", "/account/verify", Check]] }, { title: "Privacy", color: "#b054ff", items: [["Privacy", "/settings/privacy", Eye], ["Blocked Users", "/blocked-users", Lock]] }, { title: "Security", color: "#ff6eb4", items: [["Two-factor authentication", "/settings/security", Shield], ["Active sessions", "/settings/security", Shield]] }, { title: "About", color: "#7eb9ff", items: [["Help Center", "/help", Info], ["Feedback", "/feedback", Info], ["App version 1.0.0", "/settings/about", Info]] }] as const; return <PageShell><TopBar title="Settings" /><button onClick={() => navigate("/profile")} className="w-full flex items-center gap-3 px-4 py-4 border-b border-white/[.06] text-left"><Avatar user={currentUser} size="md" ring /><div className="flex-1"><p className="font-semibold">{currentUser.displayName}</p><p className="text-white/50 text-sm">@{currentUser.username}</p></div><ChevronRight size={18} className="text-white/30" /></button><div className="px-4 py-4 border-b border-white/[.06]"><p className="text-white/50 text-xs font-semibold uppercase tracking-wider mb-3">Appearance</p><div className="flex gap-3"><button onClick={() => setTheme("dark")} className="flex-1 flex items-center gap-2 px-3 py-3 rounded-xl" style={{ background: theme === "dark" ? "rgba(255,0,110,.12)" : "rgba(255,255,255,.05)", border: theme === "dark" ? "1px solid rgba(255,0,110,.4)" : "1px solid rgba(255,255,255,.08)" }}><Moon size={16} className="text-pink-400" /><span className="text-sm">Dark mode</span></button><button onClick={() => setTheme("light")} className="flex-1 flex items-center gap-2 px-3 py-3 rounded-xl" style={{ background: theme === "light" ? "rgba(255,0,110,.12)" : "rgba(255,255,255,.05)", border: theme === "light" ? "1px solid rgba(255,0,110,.4)" : "1px solid rgba(255,255,255,.08)" }}><Sun size={16} className="text-white/50" /><span className="text-sm text-white/60">Light mode</span></button></div></div>{sections.map((section) => <div key={section.title} className="px-4 py-4 border-b border-white/[.06]"><p className="text-white/50 text-xs font-semibold uppercase tracking-wider mb-3">{section.title}</p><div className="rounded-2xl overflow-hidden bg-white/[.03] border border-white/[.07]">{section.items.map(([label, href, Icon], index) => <button key={label} onClick={() => navigate(href)} className="w-full flex items-center gap-3 px-4 py-3.5 text-left" style={{ borderBottom: index < section.items.length - 1 ? "1px solid rgba(255,255,255,.06)" : "none" }}><span className="w-8 h-8 rounded-lg flex items-center justify-center" style={{ background: `${section.color}18` }}><Icon size={16} style={{ color: section.color }} /></span><span className="flex-1 text-white/80 text-sm">{label}</span><ChevronRight size={14} className="text-white/25" /></button>)}</div></div>)}<div className="px-4 py-4"><button onClick={() => setLogout(true)} className="w-full flex items-center gap-3 px-4 py-3.5 rounded-2xl bg-red-500/10 border border-red-500/20"><LogOut size={18} className="text-red-400" /><span className="text-red-400 font-medium text-sm">Log out</span></button></div>{logout && <div className="fixed inset-0 z-50 bg-black/70 flex items-center justify-center px-6"><div className="w-full max-w-sm rounded-2xl overflow-hidden bg-[#120f1e] border border-white/10"><div className="p-6"><h3 className="font-bold text-lg mb-2">Log out?</h3><p className="text-white/60 text-sm">You can come back anytime.</p></div><div className="flex border-t border-white/10"><button onClick={() => setLogout(false)} className="flex-1 py-4 text-white/60 border-r border-white/10">Cancel</button><button onClick={() => { localStorage.removeItem("yuniko-demo-auth"); navigate("/login"); }} className="flex-1 py-4 text-red-400 font-semibold">Log out</button></div></div></div>}</PageShell>; }

function PostDetail() { const params = useParams<{ postId?: string }>(); const post = posts.find((item) => item.id === params.postId) ?? posts[0]; return <PageShell><TopBar title="Post" /><div className="max-w-2xl mx-auto px-3 pt-3"><div className="aspect-[4/5] rounded-2xl overflow-hidden"><PostCard post={post} /></div></div></PageShell>; }
function GenericPage({ title, icon, body }: { title: string; icon: ReactNode; body: string }) { return <PageShell><TopBar title={title} /><EmptyState icon={icon} title={title} body={body} /></PageShell>; }

function AnimatedRoutes({ onLogin }: { onLogin: () => void }) { const [location] = useLocation(); const previous = useRef(location); const [direction, setDirection] = useState<"forward" | "back">("forward"); useEffect(() => { if (location !== previous.current) { setDirection("forward"); previous.current = location; } }, [location]); return <div className="relative overflow-hidden yuniko-route-shell"><AnimatePresence mode="popLayout" initial={false}><motion.div key={location} initial={{ x: direction === "forward" ? "100%" : "-100%", opacity: 1 }} animate={{ x: 0, opacity: 1 }} exit={{ x: direction === "forward" ? "-100%" : "100%", opacity: 1 }} transition={{ duration: .22, ease: [0.25, .1, .25, 1] }} className="yuniko-route-page"><Switch><Route path="/login"><Login onLogin={onLogin} /></Route><Route path="/" component={Home} /><Route path="/notifications" component={Notifications} /><Route path="/create" component={Create} /><Route path="/messages" component={Messages} /><Route path="/profile"><Profile /></Route><Route path="/user/:userId">{(params) => <Profile userId={params.userId} />}</Route><Route path="/settings" component={Settings} /><Route path="/search" component={SearchPage} /><Route path="/story/:id" component={StoryPage} /><Route path="/chat/:userId" component={Chat} /><Route path="/post/:postId" component={PostDetail} /><Route path="/add-friends" component={() => <GenericPage title="Find people" icon={<UserPlus size={28} />} body="Discover new people to follow." />} /><Route path="/followers/:userId" component={() => <GenericPage title="Followers" icon={<Users size={28} />} body="People following this account." />} /><Route path="/following/:userId" component={() => <GenericPage title="Following" icon={<Users size={28} />} body="Accounts this person follows." />} /><Route path="/profile/edit" component={() => <GenericPage title="Edit profile" icon={<User size={28} />} body="Update your profile details." />} /><Route path="/account/verify" component={() => <GenericPage title="Verify account" icon={<Check size={28} />} body="Verification helps your followers know your account is authentic." />} /><Route path="/settings/account" component={() => <GenericPage title="Username & Email" icon={<User size={28} />} body="Manage your account identity." />} /><Route path="/settings/storage" component={() => <GenericPage title="Storage" icon={<Info size={28} />} body="Manage cached media and downloads." />} /><Route path="/blocked-users" component={() => <GenericPage title="Blocked users" icon={<Lock size={28} />} body="Accounts you have blocked appear here." />} /><Route path="/settings/privacy" component={() => <GenericPage title="Privacy" icon={<Eye size={28} />} body="Choose who can see and contact you." />} /><Route path="/settings/security" component={() => <GenericPage title="Security" icon={<Shield size={28} />} body="Manage account security." />} /><Route path="/settings/about" component={() => <GenericPage title="About Yuniko" icon={<Info size={28} />} body="A vivid social space by Aora Group." />} /><Route path="/help" component={() => <GenericPage title="Help Center" icon={<Info size={28} />} body="Find answers and get support." />} /><Route path="/feedback" component={() => <GenericPage title="Feedback" icon={<MessageCircle size={28} />} body="Tell us what you think." />} /><Route component={() => <GenericPage title="Page not found" icon={<X size={28} />} body="This Yuniko page does not exist." />} /></Switch></motion.div></AnimatePresence></div>; }

function DemoRouter({ splash, onLogin }: { splash: boolean; onLogin: () => void }) {
  const [location, navigate] = useLocation();
  useEffect(() => {
    if (!splash && !localStorage.getItem("yuniko-demo-auth") && location !== "/login") navigate("/login");
  }, [location, navigate, splash]);
  return <>{!splash && !localStorage.getItem("yuniko-demo-auth") && location !== "/login" ? null : <AnimatedRoutes onLogin={onLogin} />}</>;
}

export default function App() {
  const [splash, setSplash] = useState(true);
  const doneSplash = useCallback(() => setSplash(false), []);
  const onLogin = useCallback(() => { localStorage.setItem("yuniko-demo-auth", "1"); }, []);
  return <Router base={import.meta.env.BASE_URL.replace(/\/$/, "")}><div className="yuniko-root"><AnimatePresence>{splash && <Splash onDone={doneSplash} />}</AnimatePresence>{!splash ? <DemoRouter splash={splash} onLogin={onLogin} /> : <div className="min-h-screen" />}</div></Router>;
}